void CPU_CORE_DefineCodeProtectionRange(uint32 lower_boundary, uint32 upper_boundary, uint32 range);
void CPU_CORE_EnableDataRead(uint32 protection_set, uint32 range);
void CPU_CORE_EnableDataWrite(uint32 protection_set, uint32 range);
